<div class="grid gap-4 md:grid-cols-2">
    <label class="text-sm font-medium">التدريب<select name="practice_id" required class="mt-2 w-full rounded-xl border border-border p-3"><?php foreach ($practices as $practiceOption): ?><option value="<?= e((string) $practiceOption['id']) ?>" <?= (string) ($question['practice_id'] ?? '') === (string) $practiceOption['id'] ? 'selected' : '' ?>><?= e($practiceOption['title_ar']) ?></option><?php endforeach; ?></select></label>
    <label class="text-sm font-medium">المهارة<select name="skill_id" required class="mt-2 w-full rounded-xl border border-border p-3"><?php foreach ($skills as $skillOption): ?><option value="<?= e((string) $skillOption['id']) ?>" <?= (string) ($question['skill_id'] ?? '') === (string) $skillOption['id'] ? 'selected' : '' ?>><?= e($skillOption['name_ar']) ?></option><?php endforeach; ?></select></label>
    <label class="text-sm font-medium">المقطع (اختياري)<select name="passage_id" class="mt-2 w-full rounded-xl border border-border p-3"><option value="">بدون مقطع</option><?php foreach ($passages as $passageOption): ?><option value="<?= e((string) $passageOption['id']) ?>" <?= (string) ($question['passage_id'] ?? '') === (string) $passageOption['id'] ? 'selected' : '' ?>><?= e($passageOption['title']) ?></option><?php endforeach; ?></select></label>
    <label class="text-sm font-medium">ترتيب السؤال<input type="number" min="0" name="sort_order" value="<?= e((string) ($question['sort_order'] ?? '0')) ?>" class="mt-2 w-full rounded-xl border border-border p-3"></label>
    <label class="text-sm font-medium md:col-span-2">نص السؤال (إنجليزي)<textarea name="text" required dir="ltr" rows="2" class="mt-2 w-full rounded-xl border border-border p-3"><?= e($question['text'] ?? '') ?></textarea></label>
    <?php foreach (['A' => 'option_a','B' => 'option_b','C' => 'option_c','D' => 'option_d'] as $letter => $column): ?>
        <label class="text-sm font-medium">الخيار <?= e($letter) ?><textarea name="<?= e($column) ?>" required dir="ltr" rows="2" class="mt-2 w-full rounded-xl border border-border p-3"><?= e($question[$column] ?? '') ?></textarea></label>
    <?php endforeach; ?>
    <label class="text-sm font-medium">الإجابة الصحيحة<select name="correct" required class="mt-2 w-full rounded-xl border border-border p-3"><?php foreach (['A','B','C','D'] as $letter): ?><option value="<?= e($letter) ?>" <?= ($question['correct'] ?? 'A') === $letter ? 'selected' : '' ?>><?= e($letter) ?></option><?php endforeach; ?></select></label>
    <label class="flex items-center gap-2 self-end"><input type="checkbox" name="in_placement" <?= !empty($question['in_placement']) ? 'checked' : '' ?> class="accent-green-700"> ضمن أسئلة تحديد المستوى</label>
    <label class="text-sm font-medium md:col-span-2">الشرح العربي<textarea name="explanation_ar" required rows="3" class="mt-2 w-full rounded-xl border border-border p-3"><?= e($question['explanation_ar'] ?? '') ?></textarea></label>
    <?php foreach (['A' => 'wrong_a_ar','B' => 'wrong_b_ar','C' => 'wrong_c_ar','D' => 'wrong_d_ar'] as $letter => $column): ?>
        <label class="text-sm font-medium">سبب خطأ الخيار <?= e($letter) ?><textarea name="<?= e($column) ?>" rows="2" class="mt-2 w-full rounded-xl border border-border p-3"><?= e($question[$column] ?? '') ?></textarea></label>
    <?php endforeach; ?>
    <label class="flex items-center gap-2"><input type="checkbox" name="is_active" <?= !isset($question['is_active']) || $question['is_active'] ? 'checked' : '' ?> class="accent-green-700"> تفعيل السؤال للطلاب</label>
</div>
